from homeassistant.components import websocket_api
import voluptuous as vol

@websocket_api.websocket_command({
    vol.Required("type"): "my_device/get_logs",
    vol.Required("device_id"): str,
})
@websocket_api.async_response
async def websocket_get_logs(hass, connection, msg):
    device_id = msg['device_id']
    api = hass.data[DOMAIN][msg['config_entry_id']]['api']

    try:
        logs = await api.get_device_logs(device_id)
        connection.send_result(msg['id'], logs)
    except Exception as err:
        connection.send_error(msg['id'], 'fetch_failed', str(err))
